import{_ as e,c as o,al as a,o as n}from"./chunks/framework.D3pXwl8O.js";const u=JSON.parse('{"title":"Auto Modes","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_modes_rover/auto.md","filePath":"en/flight_modes_rover/auto.md"}'),r={name:"en/flight_modes_rover/auto.md"};function i(s,t,d,m,h,l){return n(),o("div",null,t[0]||(t[0]=[a('<h1 id="auto-modes" tabindex="-1">Auto Modes <a class="header-anchor" href="#auto-modes" aria-label="Permalink to &quot;Auto Modes&quot;">​</a></h1><p>In auto modes the autopilot takes over control of the vehicle to run missions, return to launch, or perform other autonomous navigation tasks.</p><p>To use auto modes <strong>all</strong> the configuration/tuning steps in <a href="./../config_rover/">Rover Configuration/Tuning</a> must be followed (from <a href="./../config_rover/basic_setup.html">Basic Setup</a> to <a href="./../config_rover/position_tuning.html">Position tuning</a>).</p><h2 id="mission-mode" tabindex="-1">Mission Mode <a class="header-anchor" href="#mission-mode" aria-label="Permalink to &quot;Mission Mode&quot;">​</a></h2><p><em>Mission mode</em> is an automatic mode that causes the vehicle to execute a predefined autonomous <a href="./../flying/missions.html">mission plan</a> that has been uploaded to the flight controller. The mission is typically created and uploaded with a Ground Control Station (GCS) application, such as <a href="https://docs.qgroundcontrol.com/master/en/" target="_blank" rel="noreferrer">QGroundControl</a>.</p><h3 id="mission-commands" tabindex="-1">Mission commands <a class="header-anchor" href="#mission-commands" aria-label="Permalink to &quot;Mission commands&quot;">​</a></h3><p>The following commands can be used in missions at time of writing (PX4 v1.16):</p><table tabindex="0"><thead><tr><th>QGC mission item</th><th>Command</th><th>Description</th></tr></thead><tbody><tr><td>Mission start</td><td><a href="./MAV_CMD_MISSION_START.html">MAV_CMD_MISSION_START</a></td><td>Starts the mission.</td></tr><tr><td>Waypoint</td><td><a href="./MAV_CMD_NAV_WAYPOINT.html">MAV_CMD_NAV_WAYPOINT</a></td><td>Navigate to waypoint.</td></tr><tr><td>Return to launch</td><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_RETURN_TO_LAUNCH" target="_blank" rel="noreferrer">MAV_CMD_NAV_RETURN_TO_LAUNCH</a></td><td>Return to the launch location.</td></tr><tr><td>Change speed</td><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_CHANGE_SPEED" target="_blank" rel="noreferrer">MAV_CMD_DO_CHANGE_SPEED</a></td><td>Change the speed setpoint</td></tr><tr><td>Set launch location</td><td><a href="./MAV_CMD_DO_SET_HOME.html">MAV_CMD_DO_SET_HOME</a></td><td>Changes launch location to specified coordinates.</td></tr><tr><td>Jump to item (all)</td><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_JUMP" target="_blank" rel="noreferrer">MAV_CMD_DO_JUMP</a> (and other jump commands)</td><td>Jump to specified mission item.</td></tr></tbody></table><h2 id="return-mode" tabindex="-1">Return Mode <a class="header-anchor" href="#return-mode" aria-label="Permalink to &quot;Return Mode&quot;">​</a></h2><p>The vehicle will return to the launch position. Return mode can be activated through the respective <a href="#mission-commands">mission command</a> or through the ground station UI.</p>',10)]))}const c=e(r,[["render",i]]);export{u as __pageData,c as default};
